-- create "commercial_activations" table
CREATE TABLE "commercial_activations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "revision" bigint NOT NULL, PRIMARY KEY ("id"));
-- create "commercial_audit_entries" table
CREATE TABLE "commercial_audit_entries" ("order_key" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "audit_entry_id" uuid NOT NULL, "environment" character varying NOT NULL, "operation_id" uuid NOT NULL, "attempt_id" uuid NOT NULL, "actor_kind" character varying NOT NULL, "actor_id" character varying NOT NULL, "action" character varying NOT NULL, "resource_kind" character varying NOT NULL, "resource_id" character varying NOT NULL, "occurred_at" timestamptz NOT NULL, "recorded_at" timestamptz NOT NULL, "reason" text NOT NULL, "outcome" character varying NOT NULL, "before_state" jsonb NULL, "after_state" jsonb NULL, "policy_revision" character varying NOT NULL, "configuration_revision" character varying NOT NULL, "correlation_id" uuid NOT NULL, "caused_by_entry_ids" jsonb NOT NULL, "provider_references" jsonb NOT NULL, PRIMARY KEY ("order_key"));
-- create index "commercial_audit_entries_audit_entry_id_key" to table: "commercial_audit_entries"
CREATE UNIQUE INDEX "commercial_audit_entries_audit_entry_id_key" ON "commercial_audit_entries" ("audit_entry_id");
-- create index "commercialauditentry_environme_869bbbfaa42f09795e0fe802d1870606" to table: "commercial_audit_entries"
CREATE INDEX "commercialauditentry_environme_869bbbfaa42f09795e0fe802d1870606" ON "commercial_audit_entries" ("environment", "resource_kind", "resource_id", "order_key");
-- create index "commercialauditentry_environment_operation_id" to table: "commercial_audit_entries"
CREATE INDEX "commercialauditentry_environment_operation_id" ON "commercial_audit_entries" ("environment", "operation_id");
-- create "commercial_flags" table
CREATE TABLE "commercial_flags" ("flag" character varying NOT NULL, "enabled" boolean NOT NULL DEFAULT false, "all_users" boolean NOT NULL DEFAULT false, "subject_ids" jsonb NOT NULL, "updated_at" timestamptz NULL, "updated_by" uuid NULL, PRIMARY KEY ("flag"));
-- create "commercial_groups" table
CREATE TABLE "commercial_groups" ("slug" character varying NOT NULL, "name" character varying NOT NULL, "updated_at" timestamptz NOT NULL, "updated_by" uuid NOT NULL, PRIMARY KEY ("slug"));
-- create "commercial_group_members" table
CREATE TABLE "commercial_group_members" ("id" uuid NOT NULL, "group_slug" character varying NOT NULL, "user_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "commercial_group_members_commercial_groups_group" FOREIGN KEY ("group_slug") REFERENCES "commercial_groups" ("slug") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "commercial_group_members_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "commercialgroupmember_group_slug_user_id" to table: "commercial_group_members"
CREATE UNIQUE INDEX "commercialgroupmember_group_slug_user_id" ON "commercial_group_members" ("group_slug", "user_id");
-- create "commercial_operations" table
CREATE TABLE "commercial_operations" ("id" uuid NOT NULL, "environment" character varying NOT NULL, "actor_kind" character varying NOT NULL, "actor_id" character varying NOT NULL, "action" character varying NOT NULL, "resource_kind" character varying NOT NULL, "resource_id" character varying NOT NULL, "caller_key" uuid NOT NULL, "fingerprint" character varying NOT NULL, "result" jsonb NOT NULL, "authorized_revision" bigint NOT NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "commercialoperation_environmen_56f89a02d7e119c07ef831d482de929b" to table: "commercial_operations"
CREATE UNIQUE INDEX "commercialoperation_environmen_56f89a02d7e119c07ef831d482de929b" ON "commercial_operations" ("environment", "actor_kind", "actor_id", "action", "resource_kind", "resource_id", "caller_key");
-- create "commercial_operation_attempts" table
CREATE TABLE "commercial_operation_attempts" ("id" uuid NOT NULL, "fingerprint" character varying NOT NULL, "outcome" character varying NOT NULL, "at" timestamptz NOT NULL, "operation_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "commercial_operation_attempts_commercial_operations_operation" FOREIGN KEY ("operation_id") REFERENCES "commercial_operations" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
